57	VNA::VNA(AppWindow *window, QString name)
58	    : Mode(window, name, "VNA"),
59	      deembedding(traceModel),
60	      deembedding_active(false),
61	      tiles(new TileWidget(traceModel)),
62	    central(new QScrollArea)
63	{
64	    central->setWidget(tiles);
65	    central->setWidgetResizable(true);
66	    averages = 1;
67	    singleSweep = false;
68	    calMeasuring = false;
69	    calWaitFirst = false;
70	    calDialog = nullptr;
71	
72	    lastFreq = 0.0;
73	    lastPower = 0.0;
74	    lastTime = 0.0;
75	
76	    changingSettings = false;
77	    settings.sweepType = SweepType::Frequency;
78	    settings.zerospan = false;
79	
80	    traceModel.setSource(TraceModel::DataSource::VNA);
81	
82	    configurationTimer.setSingleShot(true);
83	    connect(&configurationTimer, &QTimer::timeout, this, [=](){
84	        ConfigureDevice(configurationTimerResetTraces);
85	    });
86	
87	    // Create default traces
88	    createDefaultTracesAndGraphs(2);
89	
90	    connect(&traceModel, &TraceModel::requiredExcitation, this, &VNA::ExcitationRequired);
91	
92	    // Create menu entries and connections
93	    auto calMenu = new QMenu("Calibration", window);
94	    window->menuBar()->insertMenu(window->getUi()->menuWindow->menuAction(), calMenu);
95	    actions.insert(calMenu->menuAction());
96	    auto calLoad = calMenu->addAction("Load");
97	    saveCal = calMenu->addAction("Save");
98	    calMenu->addSeparator();
99	
100	    connect(calLoad, &QAction::triggered, [=](){
101	        LoadCalibration();
102	        if(cal.getCaltype().type != Calibration::Type::None) {
103	            if(InformationBox::AskQuestion("Adjust span?", "Do you want to adjust the span to match the loaded calibration file?", false)) {
104	                SpanMatchCal();
105	            }
106	        }
107	    });
108	
109	    connect(saveCal, &QAction::triggered, [=](){
110	        SaveCalibration();
111	    });
112	
113	    connect(&cal, &Calibration::startMeasurements, this, &VNA::StartCalibrationMeasurements);
114	
115	    auto calData = calMenu->addAction("Calibration Measurements");
116	    connect(calData, &QAction::triggered, [=](){
117	        cal.edit(&traceModel);
118	    });
119	
120	    auto calEditKit = calMenu->addAction("Edit Calibration Kit");
121	    connect(calEditKit, &QAction::triggered, [=](){
122	        cal.getKit().edit([=](){
123	            if(cal.getCaltype().type != Calibration::Type::None) {
124	                cal.compute(cal.getCaltype());
125	            }
126	        });
127	    });
128	
129	    auto calElectronic = calMenu->addAction("Electronic Calibration");
130	    connect(calElectronic, &QAction::triggered, [=](){
131	        auto d = new LibreCALDialog(&cal);
132	        d->show();
133	    });
134	
135	    calMenu->addSeparator();
136	
137	    auto calViewTerms = calMenu->addAction("View error term model");
138	    connect(calViewTerms, &QAction::triggered, [=](){
139	        auto dialog = new CalibrationViewDialog(&cal, DeviceDriver::getInfo(window->getDevice()).Limits.VNA.ports);
140	        if(AppWindow::showGUI()) {
141	            dialog->show();
142	        }
143	    });
144	
145	    calMenu->addSeparator();
146	
147	    auto calImportTerms = calMenu->addAction("Import error terms as traces");
148	    calImportTerms->setEnabled(false);
149	    connect(calImportTerms, &QAction::triggered, [=](){
150	        auto import = new TraceImportDialog(traceModel, cal.getErrorTermTraces());
151	        if(AppWindow::showGUI()) {
152	            import->show();
153	        }
154	    });
155	    auto calImportMeas = calMenu->addAction("Import measurements as traces");
156	    calImportMeas->setEnabled(false);
157	    connect(calImportMeas, &QAction::triggered, [=](){
158	        auto import = new TraceImportDialog(traceModel, cal.getMeasurementTraces());
159	        if(AppWindow::showGUI()) {
160	            import->show();
161	        }
162	    });
163	
164	    calMenu->addSeparator();
165	    auto calApplyToTraces = calMenu->addAction("Apply to traces...");
166	    calApplyToTraces->setEnabled(false);
167	    connect(calApplyToTraces, &QAction::triggered, [=]() {
168	        auto manualCalibration = new ManualCalibrationDialog(traceModel, &cal);
169	        if(AppWindow::showGUI()) {
170	            manualCalibration->show();
171	        }
172	    });
173	
174	    cal.getKit().setIdealDefault();
175	
176	    calDialog = new QProgressDialog();
177	    calDialog->setCancelButtonText("Abort");
178	    calDialog->setWindowTitle("Taking calibration measurement...");
179	    calDialog->setValue(0);
180	    calDialog->setWindowModality(Qt::ApplicationModal);
181	    calDialog->reset();
182	    calDialog->setMinimumDuration(0);
183	
184	    // A modal QProgressDialog calls processEvents() in setValue(). Needs to use a queued connection to update the progress
185	    // value from within the NewDatapoint slot to prevent possible re-entrancy.
186	    connect(this, &VNA::calibrationMeasurementPercentage, calDialog, [=](int percent) {
187	        if(calMeasuring || percent == 100) {
188	            if(window->showGUI()) {
189	                calDialog->setValue(percent);
190	            }
191	        }
192	    }, Qt::QueuedConnection);
193	
194	    connect(calDialog, &QProgressDialog::canceled, this, [=]() {
195	        // the user aborted the calibration measurement
196	        calMeasuring = false;
197	        cal.clearMeasurements(calMeasurements);
198	        cal.measurementsAbort();
199	        // delete calDialog;
200	    });
201	
202	//    portExtension.setCalkit(&cal.getCalibrationKit());
203	
204	    // De-embedding menu
205	    auto menuDeembed = new QMenu("De-embedding", window);
206	    window->menuBar()->insertMenu(window->getUi()->menuWindow->menuAction(), menuDeembed);
207	    actions.insert(menuDeembed->menuAction());
208	    auto confDeembed = new QAction("Setup...", menuDeembed);
209	    confDeembed->setMenuRole(QAction::NoRole);
210	    menuDeembed->addAction(confDeembed);
211	    connect(confDeembed, &QAction::triggered, &deembedding, &Deembedding::configure);
212	
213	    enableDeembeddingAction = menuDeembed->addAction("De-embed VNA samples");
214	    enableDeembeddingAction->setCheckable(true);
215	    enableDeembeddingAction->setEnabled(false);
216	    connect(enableDeembeddingAction, &QAction::toggled, this, &VNA::EnableDeembedding);
217	
218	    auto manualDeembed = menuDeembed->addAction("De-embed traces...");
219	    manualDeembed->setEnabled(false);
220	    connect(manualDeembed, &QAction::triggered, [=]() {
221	        auto manualDeembedding = new ManualDeembeddingDialog(traceModel, &deembedding);
222	        if(AppWindow::showGUI()) {
223	            manualDeembedding->show();
224	        }
225	    });
226	
227	    connect(&deembedding, &Deembedding::optionAdded, [=](){
228	        EnableDeembedding(true);
229	        enableDeembeddingAction->setEnabled(true);
230	        manualDeembed->setEnabled(true);
231	    });
232	    connect(&deembedding, &Deembedding::allOptionsCleared, [=](){
233	        EnableDeembedding(false);
234	        enableDeembeddingAction->setEnabled(false);
235	        manualDeembed->setEnabled(false);
236	    });
237	    connect(&deembedding, &Deembedding::triggerMeasurement, [=]() {
238	        // de-embedding measurement requested
239	        wasRunningBeforeDeembeddingMeasurement = running;
240	        Run();
241	    });
242	    connect(&deembedding, &Deembedding::finishedMeasurement, [=](){
243	        if(wasRunningBeforeDeembeddingMeasurement) {
244	            Run();
245	        } else {
246	            Stop();
247	        }
248	    });
249	
250	    // Tools menu
251	    auto toolsMenu = new QMenu("Tools", window);
252	    window->menuBar()->insertMenu(window->getUi()->menuWindow->menuAction(), toolsMenu);
