691	Calibration::InterpolationType VNA::getCalInterpolation()
692	{
693	    double f_min = 0, f_max = 0;
694	    switch(settings.sweepType) {
695	    case SweepType::Last:
696	        // should never get here, use frequency values just in case
697	    case SweepType::Frequency:
698	        f_min = settings.Freq.start;
699	        f_max = settings.Freq.stop;
700	        break;
701	    case SweepType::Power:
702	        f_min = settings.Power.frequency;
703	        f_max = settings.Power.frequency;
704	        break;
705	    }
706	    return cal.getInterpolation(f_min, f_max, settings.npoints);
707	}
