709	QString VNA::getCalStyle()
710	{
711	    auto interpol = getCalInterpolation();
712	    QString style = "";
713	    switch (interpol)
714	    {
715	    case Calibration::InterpolationType::Unchanged:
716	    case Calibration::InterpolationType::Exact:
717	    case Calibration::InterpolationType::Interpolate:
718	        style = "";
719	        break;
720	
721	    case Calibration::InterpolationType::Extrapolate:
722	        style = "background-color: yellow";
723	        break;
724	    case Calibration::InterpolationType::NoCalibration:
725	        style = "background-color: red";
726	        break;
727	    }
728	    return style;
729	}
