731	QString VNA::getCalToolTip()
732	{
733	    auto interpol = getCalInterpolation();
734	    QString txt = "";
735	    switch (interpol)
736	    {
737	    case Calibration::InterpolationType::Unchanged:
738	    case Calibration::InterpolationType::Exact:
739	    case Calibration::InterpolationType::Interpolate:
740	    case Calibration::InterpolationType::Extrapolate:
741	    {
742	        QString lo = Unit::ToString(cal.getMinFreq(), "", " kMG", 5);
743	        QString hi = Unit::ToString(cal.getMaxFreq(), "", " kMG", 5);
744	        if (settings.Freq.start < cal.getMinFreq() ) { lo = "<font color=\"red\">" + lo + "</font>";}
745	        if (settings.Freq.stop > cal.getMaxFreq() ) { hi = "<font color=\"red\">" + hi + "</font>";}
746	        txt =
747	                "limits: " + lo + " - " + hi
748	                + "<br>"
749	                + "points: " + QString::number(cal.getNumPoints())
750	                + "<br>"
751	                "file: " + cal.getCurrentCalibrationFile();
752	        break;
753	    }
754	    case Calibration::InterpolationType::NoCalibration:
755	        txt = "none";
756	        break;
757	    }
758	    return txt;
759	}
