781	void VNA::initializeDevice()
782	{
783	    if(!window->getDevice()->supports(DeviceDriver::Feature::VNA)) {
784	        InformationBox::ShowError("Unsupported", "The connected device does not support VNA mode");
785	        return;
786	    }
787	    cbLogSweep->setEnabled(window->getDevice()->supports(DeviceDriver::Feature::VNALogSweep));
788	    if(!window->getDevice()->supports(DeviceDriver::Feature::VNALogSweep)) {
789	        SetLogSweep(false);
790	    }
791	
792	    bZero->setEnabled(window->getDevice()->supports(DeviceDriver::Feature::VNAZeroSpan));
793	    SetComboBoxItemEnabled(cbSweepType, 0, window->getDevice()->supports(DeviceDriver::Feature::VNAFrequencySweep));
794	    SetComboBoxItemEnabled(cbSweepType, 1, window->getDevice()->supports(DeviceDriver::Feature::VNAPowerSweep));
795	
796	    defaultCalMenu->setEnabled(true);
797	    connect(window->getDevice(), &DeviceDriver::VNAmeasurementReceived, this, &VNA::NewDatapoint, Qt::UniqueConnection);
798	    // Check if default calibration exists and attempt to load it
799	    QSettings s;
800	    auto key = "DefaultCalibration"+window->getDevice()->getSerial();
801	    if (s.contains(key)) {
802	
803	        // only load default calibration once per device. This allows the user to switch to a different calibration
804	        // and have it persist across device initializations. Only when connecting to the device again should the
805	        // default calibration be loaded
806	        if(defaultCalSerial != window->getDevice()->getSerial()) {
807	            // we have never loaded the default calibration for this device, do so now
808	            auto filename = s.value(key).toString();
809	            qDebug() << "Attempting to load default calibration file " << filename;
810	            if(QFile::exists(filename)) {
811	                if(cal.fromFile(filename)) {
812	                    qDebug() << "Calibration successful from " << filename;
813	                    defaultCalSerial = window->getDevice()->getSerial();
814	                } else {
815	                    qDebug() << "Calibration not successfull from: " << filename;
816	                }
817	            } else {
818	                qDebug() << "Calibration file not found: " << filename;
819	            }
820	        }
821	
822	        removeDefaultCal->setEnabled(true);
823	    } else {
824	        qDebug() << "No default calibration file set for this device";
825	        removeDefaultCal->setEnabled(false);
826	    }
827	    // Configure initial state of device
828	    ConstrainAndUpdateFrequencies();
829	    SettingsChanged(true);
830	    emit deviceInitialized();
831	    if(window->getDevice() && !cal.validForDevice(window->getDevice()->getSerial())) {
832	        InformationBox::ShowMessage("Invalid calibration", "The current calibration was created for a different device. You can still use it but the resulting "
833	                                    "data likely isn't useful.");
834	    }
835	}
