905	void VNA::fromJSON(nlohmann::json j)
906	{
907	    if(j.is_null()) {
908	        return;
909	    }
910	    if(j.contains("traces")) {
911	        traceModel.fromJSON(j["traces"]);
912	    }
913	    if(j.contains("tiles")) {
914	        tiles->fromJSON(j["tiles"]);
915	    }
916	    if(j.contains("markers")) {
917	        markerModel->fromJSON(j["markers"]);
918	    }
919	    if(j.contains("de-embedding")) {
920	        deembedding.fromJSON(j["de-embedding"]);
921	        EnableDeembedding(j.value("de-embedding_enabled", true));
922	    } else {
923	        EnableDeembedding(false);
924	    }
925	
926	    // sweep configuration has to go last so graphs can catch events from changed sweep
927	    if(j.contains("sweep")) {
928	        auto sweep = j["sweep"];
929	        // restore sweep settings, keep current value as default in case of missing entry
930	        SetPoints(sweep.value("points", settings.npoints));
931	        SetIFBandwidth(sweep.value("IFBW", settings.bandwidth));
932	        SetDwellTime(sweep.value("dwellTime", settings.dwellTime));
933	        SetAveraging(sweep.value("averages", averages));
934	        if(sweep.contains("frequency")) {
935	            auto freq = sweep["frequency"];
936	            SetStartFreq(freq.value("start", settings.Freq.start));
937	            SetStopFreq(freq.value("stop", settings.Freq.stop));
938	            SetSourceLevel(freq.value("power", settings.Freq.excitation_power));
939	            SetLogSweep(freq.value("log", settings.Freq.logSweep));
940	        }
941	        if(sweep.contains("power")) {
942	            auto power = sweep["power"];
943	            SetStartPower(power.value("start", settings.Power.start));
944	            SetStopPower(power.value("stop", settings.Power.stop));
945	            SetPowerSweepFrequency(power.value("frequency", settings.Power.frequency));
946	        }
947	        auto type = SweepTypeFromString(QString::fromStdString(sweep["type"]));
948	        if(type == SweepType::Last) {
949	            // default to frequency sweep
950	            type = SweepType::Frequency;
951	        }
952	        SetSweepType(type);
953	        SetSingleSweep(sweep.value("single", singleSweep));
954	    }
955	}
