957	using namespace std;
958	
959	void VNA::NewDatapoint(DeviceDriver::VNAMeasurement m)
960	{
961	    if(isActive != true) {
962	        // ignore
963	        return;
964	    }
965	
966	    if(changingSettings) {
967	        // already setting new sweep settings, ignore incoming points from old settings
968	        return;
969	    }
970	
971	    // Calculate sweep time
972	    if(m.pointNum == 0 && lastPoint > 0) {
973	        // new sweep started
974	        auto now = QDateTime::currentDateTimeUtc();
975	        auto sweepTime = lastStart.msecsTo(now);
976	        lastStart = now;
977	        qDebug() << "Sweep took"<<sweepTime<<"milliseconds";
978	    }
979	
980	    emit newRawDatapoint(m);
981	
982	    if(singleSweep && average.getLevel() == averages) {
983	        Stop();
984	        return;
985	    }
986	
987	    auto m_avg = m;
988	
989	    bool needsSegmentUpdate = false;
990	    if (settings.segments > 1) {
991	        // using multiple segments, adjust pointNum
992	        auto pointsPerSegment = ceil((double) settings.npoints / settings.segments);
993	        if (m_avg.pointNum == pointsPerSegment - 1) {
994	            needsSegmentUpdate = true;
995	        }
996	        m_avg.pointNum += pointsPerSegment * settings.activeSegment;
997	        if(m_avg.pointNum == settings.npoints - 1) {
998	            needsSegmentUpdate = true;
999	        }
1000	    }
1001	
1002	    if(m_avg.pointNum >= settings.npoints) {
1003	        qWarning() << "Ignoring point with too large point number (" << m.pointNum << ")";
1004	        return;
1005	    }
1006	
1007	    m_avg = average.process(m_avg);
1008	
1009	    TraceMath::DataType type = TraceMath::DataType::Frequency;
1010	    if(settings.zerospan) {
1011	        type = TraceMath::DataType::TimeZeroSpan;
1012	
1013	        // keep track of first point time
1014	        if(m_avg.pointNum == 0) {
1015	            settings.firstPointTime = m_avg.us;
1016	            m_avg.us = 0;
1017	        } else {
1018	            m_avg.us -= settings.firstPointTime;
1019	        }
1020	    } else {
1021	        switch(settings.sweepType) {
1022	        case SweepType::Last:
1023	        case SweepType::Frequency:
1024	            type = TraceMath::DataType::Frequency;
1025	            break;
1026	        case SweepType::Power:
1027	            type = TraceMath::DataType::Power;
1028	            break;
1029	        }
1030	    }
1031	
1032	    lastFreq = m_avg.frequency;
1033	    lastPower = m_avg.dBm;
1034	    lastTime = (double) m_avg.us / 1000000;
1035	
1036	    window->addStreamingData(m_avg, AppWindow::VNADataType::Raw, settings.zerospan);
1037	
1038	    if(average.settled()) {
1039	        setOperationPending(false);
1040	    }
1041	
1042	    if(calMeasuring) {
1043	        if(average.currentSweep() == averages) {
1044	            // this is the last averaging sweep, use values for calibration
1045	            if(!calWaitFirst || m_avg.pointNum == 0) {
1046	                calWaitFirst = false;
1047	                cal.addMeasurements(calMeasurements, m_avg);
1048	                if(m_avg.pointNum == settings.npoints - 1) {
1049	                    calMeasuring = false;
1050	                    cal.measurementsComplete();
1051	                }
1052	            }
1053	        }
1054	        int percentage = (((average.currentSweep() - 1) * 100) + (m_avg.pointNum + 1) * 100 / settings.npoints) / averages;
1055	        emit calibrationMeasurementPercentage(percentage);
1056	    }
1057	
1058	    cal.correctMeasurement(m_avg);
1059	
1060	    if(cal.getCaltype().type != Calibration::Type::None) {
1061	        window->addStreamingData(m_avg, AppWindow::VNADataType::Calibrated, settings.zerospan);
1062	    }
1063	
1064	    traceModel.addVNAData(m_avg, type, false);
1065	    if(deembedding_active) {
1066	        deembedding.Deembed(m_avg);
1067	        window->addStreamingData(m_avg, AppWindow::VNADataType::Deembedded, settings.zerospan);
1068	        traceModel.addVNAData(m_avg, type, true);
1069	    }
1070	
1071	
1072	    emit dataChanged();
1073	    if(m_avg.pointNum == settings.npoints - 1) {
1074	        UpdateAverageCount();
1075	        markerModel->updateMarkers();
1076	    }
1077	
1078	    if(m_avg.pointNum > 0 && m_avg.pointNum != (unsigned int) (lastPoint + 1)) {
1079	        qWarning() << "Got point" << m_avg.pointNum << "but last received point was" << lastPoint << "("<<(m_avg.pointNum-lastPoint-1)<<"missed points)";
1080	    }
1081	    lastPoint = m_avg.pointNum;
1082	
1083	    if (needsSegmentUpdate) {
1084	        if( settings.activeSegment < settings.segments - 1) {
1085	            settings.activeSegment++;
1086	        } else {
1087	            settings.activeSegment = 0;
1088	        }
1089	        SettingsChanged(false, 0);
1090	    }
1091	}
