1165	void VNA::SetCenterFreq(double freq)
1166	{
1167	    auto old_span = settings.Freq.stop - settings.Freq.start;
1168	    if (freq - old_span / 2 <= DeviceDriver::getInfo(window->getDevice()).Limits.VNA.minFreq) {
1169	        // would shift start frequency below minimum
1170	        settings.Freq.start = 0;
1171	        settings.Freq.stop = 2 * freq;
1172	    } else if(freq + old_span / 2 >= DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxFreq) {
1173	        // would shift stop frequency above maximum
1174	        settings.Freq.start = 2 * freq - DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxFreq;
1175	        settings.Freq.stop = DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxFreq;
1176	    } else {
1177	        settings.Freq.start = freq - old_span / 2;
1178	        settings.Freq.stop = freq + old_span / 2;
1179	    }
1180	    ConstrainAndUpdateFrequencies();
1181	}
