1183	void VNA::SetSpan(double span)
1184	{
1185	    auto maxFreq = DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxFreq;
1186	    auto old_center = (settings.Freq.start + settings.Freq.stop) / 2;
1187	    if(old_center < DeviceDriver::getInfo(window->getDevice()).Limits.VNA.minFreq + span / 2) {
1188	        // would shift start frequency below minimum
1189	        settings.Freq.start = DeviceDriver::getInfo(window->getDevice()).Limits.VNA.minFreq;
1190	        settings.Freq.stop = DeviceDriver::getInfo(window->getDevice()).Limits.VNA.minFreq + span;
1191	    } else if(old_center > maxFreq - span / 2) {
1192	        // would shift stop frequency above maximum
1193	        settings.Freq.start = maxFreq - span;
1194	        settings.Freq.stop = maxFreq;
1195	    } else {
1196	        settings.Freq.start = old_center - span / 2;
1197	         settings.Freq.stop = settings.Freq.start + span;
1198	    }
1199	    ConstrainAndUpdateFrequencies();
1200	}
