1325	    if (points > DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxPoints) {
1326	        // needs segmented sweep
1327	        settings.segments = ceil((double) points / DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxPoints);
1328	        settings.activeSegment = 0;
