1667	void VNA::ConstrainAndUpdateFrequencies()
1668	{
1669	    if(settings.sweepType == SweepType::Frequency && settings.Freq.logSweep) {
1670	        if(settings.Freq.start <= 0) {
1671	            // start frequency must be positive, force it to 1 Hz
1672	            settings.Freq.start = 1.0;
1673	        }
1674	    }
1675	    if(settings.Freq.stop > DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxFreq) {
1676	        settings.Freq.stop = DeviceDriver::getInfo(window->getDevice()).Limits.VNA.maxFreq;
1677	    }
1678	    if(settings.Freq.start > settings.Freq.stop) {
1679	        settings.Freq.start = settings.Freq.stop;
1680	    }
1681	    if(settings.Freq.start < DeviceDriver::getInfo(window->getDevice()).Limits.VNA.minFreq) {
1682	        settings.Freq.start = DeviceDriver::getInfo(window->getDevice()).Limits.VNA.minFreq;
1683	    }
1684	    settings.zerospan = (settings.sweepType == SweepType::Frequency && settings.Freq.start == settings.Freq.stop)
1685	            || (settings.sweepType == SweepType::Power && settings.Power.start == settings.Power.stop);
1686	    emit startFreqChanged(settings.Freq.start);
1687	    emit stopFreqChanged(settings.Freq.stop);
1688	    emit spanChanged(settings.Freq.stop - settings.Freq.start);
1689	    emit centerFreqChanged((settings.Freq.stop + settings.Freq.start)/2);
1690	    SettingsChanged();
1691	}
