1772	void VNA::createDefaultTracesAndGraphs(int ports)
1773	{
1774	    auto getDefaultColor = [](int ports, int i, int j)->QColor {
1775	        // Default colors for up to four ports, ensures that e.g. S21 always has the same color
1776	        const array<vector<QColor>, 4> defaultColors = {{
1777	            {Qt::yellow},
1778	            {Qt::yellow, Qt::blue, Qt::green, Qt::red},
1779	            {Qt::yellow, Qt::blue, Qt::cyan, Qt::green, Qt::red, Qt::darkGreen, Qt::darkBlue, Qt::darkYellow, Qt::magenta},
1780	            {Qt::yellow, Qt::blue, Qt::cyan, Qt::darkCyan, Qt::green, Qt::red, Qt::darkGreen, Qt::gray, Qt::darkBlue, Qt::darkYellow, Qt::magenta, Qt::darkMagenta, Qt::cyan, Qt::darkGray, Qt::lightGray, Qt::darkRed},
1781	        }};
1782	
1783	        if(ports >= 1 && ports <= 4) {
1784	            return defaultColors[ports-1][i*ports+j];
1785	        } else {
1786	            // not enough predefined colors available for all ports, just cycle through list
1787	            const array<QColor, 16> list = {{
1788	                Qt::yellow, Qt::blue, Qt::green, Qt::red, Qt::cyan, Qt::magenta, Qt::yellow, Qt::darkRed, Qt::darkGreen, Qt::darkBlue, Qt::gray, Qt::darkCyan, Qt::darkMagenta, Qt::darkYellow, Qt::darkGray, Qt::lightGray
1789	            }};
1790	            auto index = (i*ports+j) % list.size();
1791	            return list[index];
1792	        }
1793	    };
1794	
1795	    if(ports > 1) {
1796	        vector<vector<TracePlot*>> plots;
1797	        for(int i=0;i<ports;i++) {
1798	            plots.push_back(vector<TracePlot*>());
1799	            for(int j=0;j<ports;j++) {
1800	                QString param = "S"+QString::number(i+1)+QString::number(j+1);
1801	                auto trace = new Trace(param, getDefaultColor(ports, i, j), param);
1802	                traceModel.addTrace(trace);
1803	                TracePlot *plot = TracePlot::createDefaultPlotForTrace(traceModel, trace);
1804	                plot->updateSpan(settings.Freq.start, settings.Freq.stop);
1805	                plot->enableTrace(trace, true);
1806	                plots[i].push_back(plot);
1807	            }
1808	        }
1809	        // Add created graphs to tiles
1810	        tiles->clear();
1811	        TileWidget *tile = tiles;
1812	        for(int i=0;i<ports;i++) {
1813	            TileWidget *row;
1814	            if(i != ports - 1) {
1815	                // this is not the last row, split tile
1816	                tile->splitVertically();
1817	                row = tile->Child1();
1818	                tile = tile->Child2();
1819	            } else {
1820	                row = tile;
1821	            }
1822	            for(int j=0;j<ports;j++) {
1823	                TileWidget *graphTile;
1824	                if(j != ports - 1) {
1825	                    row->splitHorizontally();
1826	                    graphTile = row->Child1();
1827	                    row = row->Child2();
1828	                } else {
1829	                    graphTile = row;
1830	                }
1831	                graphTile->setPlot(plots[i][j]);
1832	            }
1833	        }
1834	        if(ports >= 3) {
1835	            // default split at the middle does not result in all plots being the same size, adjust
1836	            tile = tiles;
1837	            for(int i=0;i<ports;i++) {
1838	                TileWidget *rowTile;
1839	                if(i < ports - 1) {
1840	                    tile->setSplitPercentage(100 / (ports - i));
1841	                    rowTile = tile->Child1();
1842	                } else {
1843	                    rowTile = tile;
1844	                }
1845	                for(int j=0;j<ports-1;j++) {
1846	                    rowTile->setSplitPercentage(100 / (ports - j));
1847	                    rowTile = rowTile->Child2();
1848	                }
1849	                tile = tile->Child2();
1850	            }
1851	        }
1852	    } else if(ports == 1) {
1853	        tiles->clear();
1854	        tiles->splitHorizontally();
1855	        auto trace = new Trace("S11", getDefaultColor(ports, 0, 0), "S11");
1856	        traceModel.addTrace(trace);
1857	        auto smithchart = new TraceSmithChart(traceModel);
1858	        auto xyplot = new TraceXYPlot(traceModel);
1859	        smithchart->updateSpan(settings.Freq.start, settings.Freq.stop);
1860	        smithchart->enableTrace(trace, true);
1861	        xyplot->updateSpan(settings.Freq.start, settings.Freq.stop);
1862	        xyplot->enableTrace(trace, true);
1863	        tiles->Child1()->setPlot(smithchart);
1864	        tiles->Child2()->setPlot(xyplot);
1865	    }
1866	}
