1974	void VNA::ConfigureDevice(bool resetTraces, std::function<void(bool)> cb)
1975	{
1976	    configurationTimer.stop();
1977	    if(running) {
1978	        if (resetTraces) {
1979	            ResetLiveTraces();
1980	        }
1981	        changingSettings = true;
1982	        // assemble VNA protocol settings
1983	        DeviceDriver::VNASettings s = {};
1984	        s.IFBW = settings.bandwidth;
1985	        if(Preferences::getInstance().Acquisition.alwaysExciteAllPorts) {
1986	            for(unsigned int i=1;i<=DeviceDriver::getInfo(window->getDevice()).Limits.VNA.ports;i++) {
1987	                s.excitedPorts.push_back(i);
1988	            }
1989	        } else {
1990	            if(deembedding.isMeasuring()) {
1991	                // use the required ports for the de-embedding measurement
1992	                for(auto p : deembedding.getAffectedPorts()) {
1993	                    s.excitedPorts.push_back(p);
1994	                }
1995	            } else {
1996	                // use the required ports from the trace model
1997	                for(unsigned int i=1;i<=DeviceDriver::getInfo(window->getDevice()).Limits.VNA.ports;i++) {
1998	                    if(traceModel.PortExcitationRequired(i)) {
1999	                        s.excitedPorts.push_back(i);
2000	                    }
2001	                }
2002	            }
2003	        }
2004	        settings.excitedPorts = s.excitedPorts;
2005	
2006	        double start = settings.sweepType == SweepType::Frequency ? settings.Freq.start : settings.Power.start;
2007	        double stop = settings.sweepType == SweepType::Frequency ? settings.Freq.stop : settings.Power.stop;
2008	        int npoints = settings.npoints;
2009	        traceModel.setSpan(start, stop);
2010	        if (settings.segments > 1) {
2011	            // more than one segment, adjust start/stop
2012	            npoints = ceil((double) settings.npoints / settings.segments);
2013	            unsigned int segmentStartPoint = npoints * settings.activeSegment;
2014	            unsigned int segmentStopPoint = segmentStartPoint + npoints - 1;
2015	            if(segmentStopPoint >= settings.npoints) {
2016	                segmentStopPoint = settings.npoints - 1;
2017	                npoints = settings.npoints - segmentStartPoint;
2018	            }
2019	            auto seg_start = Util::Scale<double>(segmentStartPoint, 0, settings.npoints - 1, start, stop);
2020	            auto seg_stop = Util::Scale<double>(segmentStopPoint, 0, settings.npoints - 1, start, stop);
2021	            start = seg_start;
2022	            stop = seg_stop;
2023	        }
2024	
2025	        if(settings.sweepType == SweepType::Frequency) {
2026	            s.freqStart = start;
2027	            s.freqStop = stop;
2028	            s.points = npoints;
2029	            s.dBmStart = settings.Freq.excitation_power;
2030	            s.dBmStop = settings.Freq.excitation_power;
2031	            s.logSweep = settings.Freq.logSweep;
2032	        } else if(settings.sweepType == SweepType::Power) {
2033	            s.freqStart = settings.Power.frequency;
2034	            s.freqStop = settings.Power.frequency;
2035	            s.points = npoints;
2036	            s.dBmStart = start;
2037	            s.dBmStop = stop;
2038	            s.logSweep = false;
2039	        }
2040	        s.dwellTime = settings.dwellTime;
2041	        if(window->getDevice() && isActive) {
2042	            window->getDevice()->setVNA(s, [=](bool res){
2043	                // device received command, reset traces now
2044	                if (resetTraces) {
2045	                    ResetLiveTraces();
2046	                }
2047	                if(cb) {
2048	                    cb(res);
2049	                }
2050	                changingSettings = false;
2051	                lastStart = QDateTime::currentDateTimeUtc();
2052	                lastPoint = -1;
2053	            });
2054	            emit sweepStarted();
2055	        } else {
2056	            // no device, unable to start sweep
2057	            emit sweepStopped();
2058	            changingSettings = false;
2059	        }
2060	    } else {
2061	        if(window->getDevice() && isActive) {
2062	            changingSettings = true;
2063	            window->getDevice()->setIdle([=](bool){
2064	                changingSettings = false;
2065	            });
2066	        } else {
2067	            emit sweepStopped();
2068	            changingSettings = false;
2069	        }
2070	        emit sweepStopped();
2071	    }
2072	}
